1	// ============================================================================
2	// BNS (Bigwash Native Shell) - 데이터 모델
3	// ============================================================================
4	// HTTP 요청/응답, API 데이터 구조 정의
5	
6	module bns_models {
7	    // === HTTP 요청 ===
8	    struct HttpRequest {
9	        method:      string;     // "GET", "POST", "SSE"
10	        path:        string;     // "/api/status", "/api/gogs", ...
11	        query:       string;     // "?repo=zero-copy-db"
12	        body:        string;     // POST 바디
13	        headers:     [string];   // 헤더 배열
14	    }
15	
16	    // === HTTP 응답 ===
17	    struct HttpResponse {
18	        status_code: i32;        // 200, 404, 500
19	        content_type: string;    // "application/json", "text/event-stream"
20	        body:        string;     // 응답 바디
21	        is_sse:      bool;       // true면 Server-Sent Events
22	    }
23	
24	    // === Project 상태 ===
25	    struct ProjectStatus {
26	        name:        string;     // "Zero-Copy-DB"
27	        phase:       i32;        // 11
28	        lines:       i32;        // 22439
29	        files:       i32;        // 56
30	        tests:       i32;        // 182
31	        status:      string;     // "✅ COMPLETE"
32	    }
33	
34	    // === Gogs 커밋 정보 ===
35	    struct GogsCommit {
36	        hash:        string;     // "2bc0873"
37	        message:     string;     // "perf: 성능 최적화"
38	        repo:        string;     // "zero-copy-db"
39	        date:        string;     // "2026-03-29"
40	        files_changed: i32;      // 2
41	        insertions:  i32;        // 89
42	        deletions:   i32;        // 45
43	    }
44	
45	    // === SSE 이벤트 ===
46	    struct SseEvent {
47	        event_type:  string;     // "commit", "test", "build"
48	        data:        string;     // JSON 문자열
49	        timestamp:   i64;        // Unix timestamp
50	    }
51	
52	    // === API 응답 - Status ===
53	    struct ApiStatusResponse {
54	        last_update: string;
55	        projects:    [ProjectStatus];
56	        total_lines: i32;
57	        total_tests: i32;
58	    }
59	
60	    // === API 응답 - Gogs ===
61	    struct ApiGogsResponse {
62	        recent_commits: [GogsCommit];
63	        repo_count:     i32;
64	        total_commits:  i32;
65	    }
66	
67	    // === 에러 응답 ===
68	    struct ApiError {
69	        error:       string;
70	        message:     string;
71	        code:        i32;
72	    }
73	
74	    // === 상수 ===
75	    const HTTP_OK:              i32 = 200;
76	    const HTTP_BAD_REQUEST:     i32 = 400;
77	    const HTTP_NOT_FOUND:       i32 = 404;
78	    const HTTP_INTERNAL_ERROR:  i32 = 500;
79	
80	    const CONTENT_JSON:         string = "application/json; charset=utf-8";
81	    const CONTENT_SSE:          string = "text/event-stream";
82	    const CONTENT_TEXT:         string = "text/plain";
83	
84	    // === 헬퍼 함수 ===
85	    func http_response_ok(body: string, content_type: string) -> HttpResponse {
86	        let resp: HttpResponse;
87	        resp.status_code = HTTP_OK;
88	        resp.body = body;
89	        resp.content_type = content_type;
90	        resp.is_sse = false;
91	        return resp;
92	    }
93	
94	    func http_response_error(code: i32, message: string) -> HttpResponse {
95	        let resp: HttpResponse;
96	        resp.status_code = code;
97	        resp.body = "{\"error\": \"" + message + "\"}";
98	        resp.content_type = CONTENT_JSON;
99	        resp.is_sse = false;
100	        return resp;
101	    }
102	
103	    func http_response_sse(data: string) -> HttpResponse {
104	        let resp: HttpResponse;
105	        resp.status_code = HTTP_OK;
106	        resp.body = "data: " + data + "\n\n";
107	        resp.content_type = CONTENT_SSE;
108	        resp.is_sse = true;
109	        return resp;
110	    }
111	}
