        c2.date = "2026-03-28";
        c2.files_changed = 4;
        c2.insertions = 1358;
        c2.deletions = 0;
        commits[1] = c2;

        // Commit 3
        let c3: bns_models.GogsCommit;
        c3.hash = "8e47b1f";
        c3.message = "Query Parser Phase 10: SQL-like 파싱 엔진";
        c3.repo = "zero-copy-db";
        c3.date = "2026-03-28";
        c3.files_changed = 1;
        c3.insertions = 557;
        c3.deletions = 0;
        commits[2] = c3;

        // JSON 구성
