  Map<String, dynamic> toJson() => {
    if (eventType != null) 'event_type': eventType,
    if (message != null) 'message': message,
    if (status != null) 'status': status,
    if (data != null) 'data': data,
    if (timestamp != null) 'timestamp': timestamp,
  };
}

