    'name': name,
    'phase': phase,
    'modules': modules,
    'total_lines': totalLines,
    'memory_usage_mb': memoryUsageMb,
    'active_transactions': activeTransactions,
    'cached_queries': cachedQueries,
    'performance': performance.toJson(),
  };
}

