			return Operand{}, err
		}
		g.emit(Instruction{
			Op:   OpParam,
			Src1: argOp,
		})
	}

	// Emit call
	result := g.newTemp()
	g.emit(Instruction{
		Op:   OpCall,
		Dest: result,
		Fn:   fnName,
	})

	return result, nil
}

